import React, { useRef, useState, useEffect } from 'react';
import './Product.css';
import LD1 from "../assets/images/LD-250W.png";
import LD2 from "../assets/images/LD-250W_RF.png";
import LD3 from "../assets/images/LD-250W_BST.png";
import LD4 from "../assets/images/LD-RGB_BST.png";
import LD5 from "../assets/images/LD-RGB.png";
import DM1 from "../assets/images/DM-400LN.jpg";
import DM2 from "../assets/images/DM-1000W.jpg";
import DM3 from "../assets/images/DM-400B.png";
import DM4 from "../assets/images/DM-400B-RF.png";
import Img1 from "../assets/images/img1.jpeg";
import Img2 from "../assets/images/img2.jpeg";
import Img3 from "../assets/images/img3.jpeg";
import Img4 from "../assets/images/img4.jpeg";
import Img5 from "../assets/images/img5.jpeg";
import Img6 from "../assets/images/img6.jpeg";

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);


useEffect(() => {
  const observer = new IntersectionObserver(
    ([entry]) => {
      if (entry.isIntersecting) {
        setIsVisible(true);
        observer.disconnect();
      }
    },
    { threshold: 0.3 } // Trigger when 30% of section is visible
  );

  if (sectionRef.current) {
    observer.observe(sectionRef.current);
  }

  return () => observer.disconnect();
}, []);

  // Data structure for categories and products
  const categories = [
    {
      name: "MASTER SMART HOME",
      image: Img1,
      products: [
        { name: "ILLUMINATION", description: "Smart lighting control (Wi-Fi)", image: Img1 },
        { name: "SHADING SYSTEMS", description: "Smart awnings and shutters (Wi-Fi)", image: Img2 },
        { name: "APPLIANCES CONTROL", description: "Smart appliance control (Wi-Fi)", image: Img3 },
        { name: "HEATING / COOLING", description: "Smart heating and cooling (Wi-Fi)", image: Img4 },
        { name: "VISUALIZATION", description: "Smart control and management (Wi-Fi)", image: Img5 }
      ]
    },
    {
      name: "LED CONTROLLERS",
      image: Img2,
      products: [
        { name: "LD-250W", description: "Led Controller LD-250W was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: LD1 },
        { name: "LD-250W-RF", description: "Led Controller LD-250W-RF was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: LD2 },
        { name: "LD-250W-BST", description: "Led Controller LD-250W-BST (Booster-Amplifier one channel) was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: LD3 },
        { name: "LD-RGB-BST", description: "Led Controller LD-RGB-BST (Booster-Amplifier three channels) was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes, Led bulbs, etc. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: LD4 },
        { name: "LD-RGB", description: "Led Controller LD-RGB was designed to fulfill the needs of illumination control and management of lighting fixtures using LED technology at 12VDC and 24VDC like Led Stripes and R-G-B projectors. It is a safe and reliable product because it was designed with special integrated circuits and plastic parts for adverse operating conditions.", image: LD5 }
      ]
    },
    {
      name: "WALL – MOUNTING DIMMER",
      image: Img3,
      products: [
        { name: "DM-400L/N", description: "The DM-400L/N (Dimmer) is an innovative digital technology product (Phase-cut) with switchable Leading Edge - Trailing Edge operation.It fully meets the needs of light intensity adjustment and energy saving, especially when using alternative LED Filament, LED Dimmable, CFL, Halogen lamps and Dimmable Drivers.It is an absolutely safe, reliable, and aesthetically elegant product made with special state-of-the-art integrated circuits and durable plastic parts for challenging operating and usage conditions.Its operation locally from the device and remotely from one or more parallel-connected push buttons of any type and manufacturer makes it unique.", image: DM1 },
        { name: "DM-1000W", description: "DM - 1000W  wall mounting dimmer wasdesigned to cover the needs on lighting and ventilation control on house and partly professional fields. It is an absolutely safe, reliable and good looking product manufactured with special integrated circuits and good quality, resistant plastic parts for cases of function and use under adverse conditions, equipped with one of the best antiparasitic systems.", image: DM2 }
      ]
    },
    {
      name: "FLUSH – MOUNTING DIMMER",
      image: Img4,
      products: [
        { name: "DM-400B", description: "Dimmer DM-400B (Lighting Controller) is an innovative product of digital technology Leading Edge & Trailing Edge, specially created to fully cover the needs for regulation of lighting intensity and for energy saving, using alternative type of lamps such as LED (dimmable LED), economy lamps (dimmable CFL ) and previous generation light bulbs (Resistive - Halogen).", image: DM3 },
        { name: "DM-400B-RF", description: "Dimmer DM-400B-RF (Lighting Controller) is an innovative product of digital technology Leading Edge & Trailing Edge, specially created to fully cover the needs for regulation of lighting intensity and for energy saving, using alternative type of lamps such as LED (dimmable LED), economy lamps (dimmable CFL ) and previous generation light bulbs (Resistive - Halogen).", image: DM4 }
      ]
    },
    {
      name: "RAIL – MOUNTING DIGITAL DIMMER",
      image: Img5,
      products: [
        { name: "DM-300/b", description: "Rail Mounting Dimmer 300W LED (Remote Control)", image: Img3 },
        { name: "DM-DGL/b", description: "Rail Mounting Digital Dimmer 1000W", image: Img4 }
      ]
    },
    {
      name: "SURFACE – MOUNTING DIMMER",
      image: Img6,
      products: [
        { name: "DM-2500W", description: "Dimmer Professional Multi-LED 2500W", image: Img5 },
        { name: "DM-2500", description: "Dimmer Professional Multi-LED 2500W", image: Img6 },
        { name: "DM-PRO 1-10V", description: "Dimmer Professional 1-10V", image: Img1 }
      ]
    }
    // Add more categories and products here
  ];

  // Handle back to category view
  const goBack = () => {
    setSelectedCategory(null);
    setSelectedProduct(null);
  };

  return (
    <section ref={sectionRef} className={`products-section fade-in-section ${isVisible ? 'visible' : ''}`}>
    <div className="container">
    <div className="products-section">
      <div className="container">

        {/* ======= CATEGORY VIEW ======= */}
        {!selectedCategory && (
          <>
            <h2 className="products-title">Our Products</h2>
            <div className="category-grid">
              {categories.map((category, index) => (
                <div key={index} className="category-card">
                  <img src={category.image} alt={category.name} />
                  <h3>{category.name}</h3>
                  <button onClick={() => setSelectedCategory(category)}>View Products</button>
                </div>
              ))}
            </div>
          </>
        )}

        {/* ======= PRODUCT VIEW ======= */}
        {selectedCategory && (
          <>
            <button className="back-button" onClick={goBack}>
  <span className="back-circle">
    ◀
  </span>
  Back to Products
</button>
            <h2 className="products-title">{selectedCategory.name}</h2>
            <div className="products-grid">
              {selectedCategory.products.map((product, index) => (
                <div
                  key={index}
                  className="product-card"
                  onClick={() => setSelectedProduct(product)}
                >
                  <img src={product.image} alt={product.name} />
                  <h4>{product.name}</h4>
                </div>
              ))}
            </div>
          </>
        )}

        {/* ======= PRODUCT MODAL ======= */}
        {selectedProduct && (
          <div className="product-modal">
            <div className="modal-content">
              <button className="close-button" onClick={() => setSelectedProduct(null)}>×</button>
              <img src={selectedProduct.image} alt={selectedProduct.name} />
              <h2>{selectedProduct.name}</h2>
              <p>{selectedProduct.description}</p>
            </div>
          </div>
        )}
      </div>
    </div>
    </div>
  </section>  
  );
};

export default Products;
